KG42.register("rules-e845240b735b26eb30cbf24a",{"id":"04-energy_collectives::v141-c-R005","paper":"04-energy_collectives","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"Collective members may trade their energy surplus or deficit within the community and import or export energy with the system operator. Scope: Energy-collective members' exchanges within the community and with the system operator.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Energy-collective members' exchanges within the community and with the system operator.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E04","v141-b-g01-E10"]},"x":[{"variable_id":"v141-c-R005-x-p_j","symbol":"p_j","meaning":"Net energy produced by prosumer j","kind":"operational","domain":"P_j (prosumer j's feasible net-production set, defined by technical constraints (1f))","unit":null,"indices":["j=1,...,n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"variable_id":"v141-c-R005-x-q_j","symbol":"q_j","meaning":"Energy imported by prosumer j from the community (positive for imports, negative for exports); the aggregate over all prosumers is zero by (1c)","kind":"operational","domain":"real-valued energy quantity (decision variable in Γ; no explicit individual bounds stated beyond the balance and aggregate zero-sum conditions)","unit":null,"indices":["j=1,...,n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"variable_id":"v141-c-R005-x-alpha_j","symbol":"α_j","meaning":"Energy imported by prosumer j from the system operator","kind":"operational","domain":"non-negative real-valued energy quantity (α_j ≥ 0 per (1g))","unit":null,"indices":["j=1,...,n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"variable_id":"v141-c-R005-x-beta_j","symbol":"β_j","meaning":"Energy exported by prosumer j to the system operator","kind":"operational","domain":"non-negative real-valued energy quantity (β_j ≥ 0 per (1g))","unit":null,"indices":["j=1,...,n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"variable_id":"v141-c-R005-x-q_imp","symbol":"q_imp","meaning":"Total energy imported by the community from the system operator; equals sum_j α_j","kind":"operational","domain":"non-negative continuous energy quantity (continuous import exchange with the system operator; equals the sum of non-negative α_j)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"variable_id":"v141-c-R005-x-q_exp","symbol":"q_exp","meaning":"Total energy exported by the community to the system operator; equals sum_j β_j","kind":"operational","domain":"non-negative continuous energy quantity (continuous export exchange with the system operator; equals the sum of non-negative β_j)","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]}],"theta":[{"parameter_id":"v141-c-R005-theta-n","symbol":"n","meaning":"Number of prosumers in the collective","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E09"]}],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Collective members may trade their energy surplus or deficit within the community and import or export energy with the system operator. Scope: Energy-collective members' exchanges within the community and with the system operator.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E04","v141-b-g01-E10"]},{"constraint_id":"v141-c-R005-C002","kind":"mathematical","role":"supporting","statement":"For each prosumer j, the power balance between net production and traded energy holds: p_j + q_j + α_j − β_j = 0.","expression":"p_j + q_j + α_j − β_j = 0, j = 1,...,n","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R005-x-p_j","v141-c-R005-x-q_j","v141-c-R005-x-alpha_j","v141-c-R005-x-beta_j"],"parameter_refs":["v141-c-R005-theta-n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"constraint_id":"v141-c-R005-C003","kind":"mathematical","role":"supporting","statement":"The imported and exported energy quantities of each prosumer are non-negative: α_j ≥ 0 and β_j ≥ 0 for all j = 1,...,n.","expression":"α_j ≥ 0; β_j ≥ 0, j = 1,...,n","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R005-x-alpha_j","v141-c-R005-x-beta_j"],"parameter_refs":["v141-c-R005-theta-n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"constraint_id":"v141-c-R005-C004","kind":"mathematical","role":"supporting","statement":"The sum of the community-internal energy exchanges over all prosumers is zero: sum_{j=1}^{n} q_j = 0.","expression":"sum_{j=1}^{n} q_j = 0","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R005-x-q_j"],"parameter_refs":["v141-c-R005-theta-n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]},{"constraint_id":"v141-c-R005-C005","kind":"mathematical","role":"supporting","statement":"The aggregate energy imported from the system operator equals the sum of individual imports, and the aggregate energy exported equals the sum of individual exports: sum_{j=1}^{n} α_j = q_imp and sum_{j=1}^{n} β_j = q_exp.","expression":"sum_{j=1}^{n} α_j = q_imp; sum_{j=1}^{n} β_j = q_exp","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R005-x-alpha_j","v141-c-R005-x-beta_j","v141-c-R005-x-q_imp","v141-c-R005-x-q_exp"],"parameter_refs":["v141-c-R005-theta-n"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"]}],"pi":[{"evidence_id":"v141-b-g01-E04","location":{"location_id":"src-dfa28329fc-p02-c1r2__v141-a-M01-participation","page":2,"printed_page":"3995","section":"I. Introduction","anchor_text":"exist to enable these market organizations, for instance on the cloud for distributed systems [9] or","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"We call this market organization energy collective and we define it as a community of prosumers that operates in a collaborative manner, optimizing usage of resources. This translates to a market framework where the collective members can trade their lack or excess of energy. The distributed nature of the market implies that all prosumers are in charge of optimizing their assets individually. Optimality is achieved as prosumers are coordinated by a non-profit virtual node, that we call community manager."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-dfa28329fc-p03-c1r3__v141-a-M01-clearing","page":3,"printed_page":"3996","section":"II. Energy Collectives and Their Operational Framework","anchor_text":"αj, βj ≥0 , j = 1, . . . , n (1g) where Γ = {pj, qj, αj, βj} is the set of decision variables and qi","equation_id":null,"figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"For each prosumer we consider technical constraints (1f) and power balance (1b) between net production, p_j, and energy traded. This energy can be traded at community level (1c) and with the system operator (1d)-(1e). Hence, we describe the energy traded by each prosumer as sum of the energy exchanged within the community, q_j, and the energy each prosumer has to respectively import, alpha_j, or export, beta_j, from outside the community, as in Fig. 1."},{"evidence_id":"v141-b-g01-E02","location":{"location_id":"src-dfa28329fc-p01-c1r3__v141-a-M01-participation","page":1,"printed_page":"3994","section":"Abstract and Nomenclature","anchor_text":"Only the most important symbols of this paper are included. αj Energy imported by prosumer j. βj Ene","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Only the most important symbols of this paper are included. alpha_j Energy imported by prosumer j. beta_j Energy exported by prosumer j. delta_j Upper bound of alpha_j. gamma Penalization coefficient (the subscript identifies the specific application). lambda_j Price of energy perceived by prosumer j. lambda_DA Day-ahead market price. P_j Feasible space of p_j. R_j Feasible space of prosumer j. U_ij Feasible space of u_ij. U-upper_ij Upper bound of asset i of prosumer j. psi_ij Cost/utility function of asset i of prosumer j. rho Penalization factor of L_rho. tau Price spread between import and export price. f-tilde_j Extended cost function of prosumer j. U-lower_ij Lower bound of asset i of prosumer j. c_ij Quadratic coefficient of psi_ij. d_ij Linear coefficient of psi_ij. f_j Cost function of prosumer j. g Model of community manager. h_j Preferences and/or transaction costs of prosumer j. I_j Set of assets of prosumer j. L_rho Augmented Lagrangian. n Number of prosumers in the collective. N_j Set of members of neighbourhood j. p_j Net energy produced by prosumer j. q_j Energy imported by prosumer j from the community. q_exp Total energy exported. q_imp Total energy imported. r_k Vector of primal residuals. s_k Vector of dual residuals. u_ij Power set-point of asset i of prosumer j. v_ij Energy traded between neighbourhood i and j. y Vector of Lagrangian multipliers."},{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-dfa28329fc-p03-c1r2__v141-a-M01-clearing","page":3,"printed_page":"3996","section":"II. Energy Collectives and Their Operational Framework","anchor_text":"as the solution of the exchange problem ad n of min fj(pj, qj, αj, βj) + g(qimp, qexp, ϑ) (1a) ap Γ ","equation_id":"(1)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"The optimal community dispatch is then obtained as the solution of the exchange problem: min_{Gamma} sum_{j=1}^{n} f_j(p_j, q_j, alpha_j, beta_j) + g(q_imp, q_exp, theta)   (1a)  s.t. p_j + q_j + alpha_j - beta_j = 0 , j = 1, . . . , n   (1b)  sum_{j=1}^{n} q_j = 0   (1c)  sum_{j=1}^{n} alpha_j = q_imp   (1d)  sum_{j=1}^{n} beta_j = q_exp   (1e)  p_j in P_j , j = 1, . . . , n   (1f)  alpha_j, beta_j >= 0 , j = 1, . . . , n   (1g)  where Gamma = {p_j, q_j, alpha_j, beta_j} is the set of decision variables and q_imp, q_exp are continuous variables describing import and export exchanges with the system operator."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E04","quote":"This translates to a market framework where the collective members can trade their lack or excess of energy."},{"evidence_id":"v141-b-g01-E10","quote":"This energy can be traded at community level (1c) and with the system operator (1d)-(1e)."}]],"C2_formalization":{"graph_sha256":"af0cbc37fcc29cdec608cdc79d057a41842b6767341e1a952983e483d96f9ec3","applicability":"formalized","reason":"The rule's core permission is procedural, but the frozen node execution.energy_trade can carry the source-supported execution mathematics: the per-prosumer power balance (1b), non-negativity of import/export (1g), the internal zero-sum condition (1c), and the aggregate import/export definitions (1d)-(1e). These are transcribed as supporting constraints from candidate-support evidence v141-b-g01-E09 and v141-b-g01-E10. The existing C001 is preserved unchanged as a procedural permission. All cited B evidence remains unreviewed candidate support.","bindings":[{"object_id":"v141-c-R005-x-p_j","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"p_j is the net production quantity that balances the trades executed under the energy-trade function; no separate node for net production exists in the frozen graph, so it is bound to execution.energy_trade."},{"object_id":"v141-c-R005-x-q_j","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"q_j is the community-internal energy exchange executed by prosumer j under execution.energy_trade."},{"object_id":"v141-c-R005-x-alpha_j","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"α_j is the system-operator import executed by prosumer j under execution.energy_trade."},{"object_id":"v141-c-R005-x-beta_j","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"β_j is the system-operator export executed by prosumer j under execution.energy_trade."},{"object_id":"v141-c-R005-x-q_imp","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"q_imp is the aggregate import quantity implied by the executed individual imports at the system-operator interface."},{"object_id":"v141-c-R005-x-q_exp","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"q_exp is the aggregate export quantity implied by the executed individual exports at the system-operator interface."},{"object_id":"v141-c-R005-theta-n","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"n is the fixed number of collective members whose energy trades instantiate the execution.energy_trade function."},{"object_id":"v141-c-R005-C001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The core procedural permission is attached to the frozen execution.energy_trade node, the only node representing the energy-trade function."},{"object_id":"v141-c-R005-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The per-prosumer power balance governs the quantity of energy traded under execution.energy_trade."},{"object_id":"v141-c-R005-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Non-negativity of imports and exports is a feasibility condition on the trades executed under execution.energy_trade."},{"object_id":"v141-c-R005-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The zero-sum of internal community exchanges is the aggregate balance condition for community trades executed under execution.energy_trade."},{"object_id":"v141-c-R005-C005","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The aggregate import/export balances link individual executed trades to the system-operator exchange quantities."}],"revision_requests":["The frozen graph contains only the node execution.energy_trade and no edge to a clearing.local or coordination.local_operator node. The exchange-problem constraints (1b)-(1e) are bound to execution.energy_trade here; C.1 should confirm whether an additional clearing node/edge is intended to represent the internal community balance relationships.","Variables p_j, q_j, α_j, β_j are declared here with source scope from v141-b-g01-E10 and v141-b-g01-E09. Because the same symbols are used in rule v141-c-R001, C.1 should confirm there is no unintended cross-rule variable reuse conflict.","B source evidence v141-b-g01-E09 and v141-b-g01-E10 remain unverified candidate support in this experiment. A subsequent B-source audit is required before the transcribed equations (1b)-(1e) and (1g) can be treated as independently verified source mathematics."]}},"quarantined_references":[]}});
